14: function ChatFrameUtil.InsertLink(text)
15: 	if ( not text ) then
16: 		return false;
17: 	end
18: 
19: 	if ( MacroFrameText and MacroFrameText:HasFocus() ) then
20: 		local item;
21: 		if ( strfind(text, "item:", 1, true) ) then
22: 			item = C_Item.GetItemInfo(text);
23: 		end
24: 		local cursorPosition = MacroFrameText:GetCursorPosition();
25: 		if (cursorPosition == 0 or strsub(MacroFrameText:GetText(), cursorPosition, cursorPosition) == "\n" ) then
26: 			if ( item ) then
27: 				if ( C_Item.GetItemSpell(text) ) then
28: 					MacroFrameText:Insert(SLASH_USE1.." "..item.."\n");
29: 				else
30: 					MacroFrameText:Insert(SLASH_EQUIP1.." "..item.."\n");
31: 				end
32: 			else
33: 				MacroFrameText:Insert(SLASH_CAST1.." "..text.."\n");
34: 			end
35: 		else
36: 			MacroFrameText:Insert(item or text);
37: 		end
38: 		return true;
39: 	end
40: 
41: 	if ( ProfessionsFrame and ProfessionsFrame.CraftingPage.RecipeList.SearchBox:HasFocus() )  then
42: 		local item;
43: 		if ( strfind(text, "item:", 1, true) ) then
44: 			item = C_Item.GetItemInfo(text);
45: 		end
46: 		if ( item ) then
47: 			ProfessionsFrame.CraftingPage.RecipeList.SearchBox:SetText(item);
48: 			return true;
49: 		end
50: 	end
51: 	if ( CommunitiesFrame and CommunitiesFrame.ChatEditBox:HasFocus() ) then
52: 		CommunitiesFrame.ChatEditBox:Insert(text);
53: 		return true;
54: 	end
55: 
56: 	local activeWindow = ChatFrameUtil.GetActiveWindow();
57: 	if ( activeWindow ) then
58: 		activeWindow:Insert(text);
59: 		activeWindow:SetFocus();
60: 		return true;
61: 	end
62: 	if ( AuctionHouseFrame and AuctionHouseFrame:IsVisible() ) then
63: 		local item;
64: 		if ( strfind(text, "battlepet:") ) then
65: 			local petName = strmatch(text, "%[(.+)%]");
66: 			item = petName;
67: 		elseif ( strfind(text, "item:", 1, true) ) then
68: 			item = C_Item.GetItemInfo(text);
69: 		end
70: 		if ( item ) then
71: 			if ( AuctionHouseFrame:SetSearchText(item) ) then
72: 				return true;
73: 			end
74: 		end
75: 	end
76: 
77: 	return false;
78: end

366: function ChatFrameUtil.OpenChat(text, chatFrame, desiredCursorPosition)
367: 	if chatFrame == nil and CHAT_FOCUS_OVERRIDE ~= nil then
368: 		if CHAT_FOCUS_OVERRIDE.supportsSlashCommands or not text or strsub(text, 0, 1) ~= "/" then
369: 			CHAT_FOCUS_OVERRIDE:SetFocus();
370: 			if text then
371: 				CHAT_FOCUS_OVERRIDE:SetText(text);
372: 			end
373: 			return;
374: 		end
375: 	end
376: 
377: 	local editBox = ChatFrameUtil.ChooseBoxForSend(chatFrame);
378: 
379: 	-- GAME RULES TODO:: This should be an explicit game rule.
380: 	if C_GameRules.GetActiveGameMode() == Enum.GameMode.Plunderstorm then
381: 		if not hasInitializedDefaultChatChannel then
382: 			hasInitializedDefaultChatChannel = true;
383: 
384: 			-- Don't default chat type if we already have a specific type (i.e. BN_WHISPER)
385: 			if editBox:GetChatType() == "SAY" then
386: 				local isInGroup;
387: 				if IsInGroup(LE_PARTY_CATEGORY_HOME) then
388: 					local groupCount = GetNumGroupMembers();
389: 					if groupCount > 1 then
390: 						isInGroup = true;
391: 					end
392: 				end
393: 
394: 				local chatType = "SAY";
395: 				if C_Glue.IsOnGlueScreen() then
396: 					chatType = "PARTY";
397: 				elseif isInGroup then
398: 					chatType = "INSTANCE_CHAT";
399: 				end
400: 
401: 				editBox:SetChatType(chatType);
402: 				editBox:SetStickyType(chatType);
403: 			end
404: 		end
405: 	end
406: 
407: 	ChatFrameUtil.ActivateChat(editBox);
408: 	editBox.desiredCursorPosition = desiredCursorPosition;
409: 
410: 	if text then
411: 		editBox.text = text;
412: 		editBox.setText = 1;
413: 	end
414: 
415: 	local stickyType = editBox:GetStickyType();
416: 	if editBox:GetChatType() == stickyType then
417: 		if ((stickyType == "PARTY") and (not IsInGroup(LE_PARTY_CATEGORY_HOME)) or
418: 			(stickyType == "RAID") and (not IsInRaid(LE_PARTY_CATEGORY_HOME)) or
419: 			(stickyType == "INSTANCE_CHAT") and (not IsInGroup(LE_PARTY_CATEGORY_INSTANCE))) then
420: 
421: 			editBox:SetChatType("SAY");
422: 		end
423: 	end
424: 
425: 	editBox:UpdateHeader();
426: 	return editBox;
427: end

41: function Model_OnMouseWheel(self, delta, maxZoom, minZoom)
42: 	maxZoom = maxZoom or self.maxZoom;
43: 	minZoom = minZoom or self.minZoom;
44: 	local zoomLevel = self.zoomLevel or minZoom;
45: 	zoomLevel = zoomLevel + delta * MODELFRAME_ZOOM_STEP;
46: 	zoomLevel = min(zoomLevel, maxZoom);
47: 	zoomLevel = max(zoomLevel, minZoom);
48: 	self:SetPortraitZoom(zoomLevel);
49: 	self.zoomLevel = zoomLevel;
50: end
